 <?php if ($tagRules): ?><div class="table-scroll"><table><thead><tr><th scope="col">规则</th><th scope="col">匹配</th><th scope="col">标签</th><th scope="col">状态</th><th scope="col">操作</th></tr></thead><tbody><?php foreach ($tagRules as $rule): ?><tr><td data-label="规则"><strong><?= e((string)$rule['name']) ?></strong><div class="muted">优先级 <?= (int)$rule['priority'] ?></div></td><td data-label="匹配"><code><?= e((string)$rule['field']) ?> <?= e((string)$rule['operator']) ?> <?= e((string)$rule['pattern']) ?></code></td><td data-label="标签"><?= e(implode(', ', (array)$rule['tags'])) ?></td><td data-label="状态"><?= (int)$rule['is_enabled'] === 1 ? '启用' : '停用' ?></td><td data-label="操作"><form method="post" action="<?= e(app_path('/workflows/tag-rules/delete')) ?>" data-confirm="确认删除这条标签规则？"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$rule['id'] ?>"><button class="button-danger button-small" type="submit"><svg class="icon"><use href="#icon-trash"/></svg>删除</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
